local ScepterMaker = {}
local PRODUCTS = {
    wooden_staff = { name = "Lesena palica", woodCost = 1, time = 1, cost = 8, prestige = 1, description = "Preprosta lesena palica za sodnike." },
    brass_scepter = { name = "Medeninasto žezlo", brassCost = 2, woodCost = 1, time = 3, cost = 40, prestige = 3, happiness = 1, description = "Medeninasto žezlo za nižje uradnike." },
    silver_scepter = { name = "Srebrno žezlo", silverCost = 2, woodCost = 1, time = 4, cost = 110, prestige = 7, happiness = 1, description = "Srebrno žezlo za plemiče." },
    gold_scepter = { name = "Zlato žezlo", goldCost = 1, silverCost = 1, woodCost = 1, time = 5, cost = 240, prestige = 12, happiness = 2, description = "Zlato žezlo za visoke plemiče." },
    jeweled_scepter = { name = "Draguljno žezlo", goldCost = 2, silverCost = 1, jewelCost = 1, time = 7, cost = 500, prestige = 20, happiness = 4, description = "Z draguljem okrašeno žezlo za kralje." },
    royal_imperial_scepter = { name = "Kraljevsko cesarsko žezlo", goldCost = 3, silverCost = 2, jewelCost = 3, pearlCost = 1, time = 10, cost = 1200, prestige = 45, happiness = 8, description = "Cesarsko žezlo z bisernim vrhom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Žezlarska delavnica", cost = { gold = 280, wood = 120 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Žezlarska kovačija", cost = { gold = 850, wood = 220, stone = 180, gold = 8 }, upkeep = 20, qualityBonus = 18 },
    jewel_setting_room = { name = "Draguljna stavilnica", cost = { gold = 1900, wood = 300, stone = 400, silver = 40, jewel = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_scepter_atelier = { name = "Kraljevski atelje žezel", cost = { gold = 7000, wood = 600, stone = 800, gold = 80, jewel = 25 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 33 },
}
ScepterMaker.woodStock = 16; ScepterMaker.brassStock = 8; ScepterMaker.silverStock = 8; ScepterMaker.goldStock = 6; ScepterMaker.jewelStock = 6; ScepterMaker.pearlStock = 4
ScepterMaker.productStock = {}; ScepterMaker.buildings = {}; ScepterMaker.maker = nil; ScepterMaker.activeMaking = {}; ScepterMaker.totalProducts = 0; ScepterMaker.dayTimer = 0
function ScepterMaker.init() ScepterMaker.woodStock=16; ScepterMaker.brassStock=8; ScepterMaker.silverStock=8; ScepterMaker.goldStock=6; ScepterMaker.jewelStock=6; ScepterMaker.pearlStock=4; ScepterMaker.productStock={}; ScepterMaker.buildings={}; ScepterMaker.maker=nil; ScepterMaker.activeMaking={}; ScepterMaker.totalProducts=0; ScepterMaker.dayTimer=0; print("[ScepterMaker] Royal Scepter Maker System initialized (6 products, 4 buildings)") end
function ScepterMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ScepterMaker.maker={name=n or ("Žezlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žezlar najet: %s (spretnost: %d)",ScepterMaker.maker.name,s),"success") end; return true end
function ScepterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ScepterMaker.build(id) local ok,e=ScepterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ScepterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ScepterMaker.getQualityBonus() local b=0; for _,bd in ipairs(ScepterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ScepterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ScepterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and ScepterMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ScepterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ScepterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ScepterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ScepterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ScepterMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ScepterMaker.maker then return false,"Potreben žezlar" end; return true end
function ScepterMaker.make(pt,qty) qty=qty or 1; local ok,e=ScepterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ScepterMaker.woodStock=ScepterMaker.woodStock-d.woodCost*qty end; if d.brassCost then ScepterMaker.brassStock=ScepterMaker.brassStock-d.brassCost*qty end; if d.silverCost then ScepterMaker.silverStock=ScepterMaker.silverStock-d.silverCost*qty end; if d.goldCost then ScepterMaker.goldStock=ScepterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ScepterMaker.jewelStock=ScepterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ScepterMaker.pearlStock=ScepterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ScepterMaker.maker then t=math.max(1,t-math.floor(ScepterMaker.maker.skill/12)) end; table.insert(ScepterMaker.activeMaking,{id="scepter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ScepterMaker.completeMaking(m) local q=1.0+(ScepterMaker.getQualityBonus()/100); if ScepterMaker.maker then q=q+(ScepterMaker.maker.skill/180) end; q=math.min(2.0,q); ScepterMaker.productStock[m.productType]=(ScepterMaker.productStock[m.productType] or 0)+m.quantity; ScepterMaker.totalProducts=ScepterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ScepterMaker.maker then ScepterMaker.maker.itemsMade=ScepterMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ScepterMaker.maker.skill=math.min(100,ScepterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žezlo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"scepter.completed",{productName=m.productName,prestige=m.prestige}) end end
function ScepterMaker.update(dt) if not _G.state then return end; ScepterMaker.dayTimer=ScepterMaker.dayTimer+dt; if ScepterMaker.dayTimer>=30 then ScepterMaker.dayTimer=0; for i=#ScepterMaker.activeMaking,1,-1 do local m=ScepterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ScepterMaker.completeMaking(m); table.remove(ScepterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ScepterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ScepterMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ScepterMaker.getStats() return {woodStock=ScepterMaker.woodStock,brassStock=ScepterMaker.brassStock,silverStock=ScepterMaker.silverStock,goldStock=ScepterMaker.goldStock,jewelStock=ScepterMaker.jewelStock,pearlStock=ScepterMaker.pearlStock,productStock=ScepterMaker.productStock,numBuildings=#ScepterMaker.buildings,hasMaker=ScepterMaker.maker~=nil,makerName=ScepterMaker.maker and ScepterMaker.maker.name or "—",makerSkill=ScepterMaker.maker and ScepterMaker.maker.skill or 0,activeMaking=#ScepterMaker.activeMaking,totalProducts=ScepterMaker.totalProducts} end
return ScepterMaker
